<script setup lang="ts">
const props = defineProps<{ ev: any }>(); const emit = defineEmits<{ refresh: [] }>(); const toast = useToast(); const { current } = useOrg()
const loc = (d: string | null) => (d ? new Date(new Date(d).getTime() - new Date(d).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : '')
const f = reactive({ title: props.ev.title, description: props.ev.description, category: props.ev.category, visibility: props.ev.visibility, startsAt: loc(props.ev.startsAt), endsAt: loc(props.ev.endsAt), salesOpenAt: loc(props.ev.salesOpenAt), salesCloseAt: loc(props.ev.salesCloseAt), capacity: props.ev.capacity, maxPerOrder: props.ev.maxPerOrder, themeId: props.ev.themeId, accessTerms: props.ev.accessTerms, templateId: props.ev.templateId ?? '', offlineEnabled: props.ev.offlineEnabled, transfersEnabled: props.ev.transfersEnabled, refundAllowed: props.ev.refundPolicy.allowed, refundHours: props.ev.refundPolicy.untilHoursBefore, accessCode: '', venueName: props.ev.location?.venueName ?? '', address: props.ev.location?.address ?? '', city: props.ev.location?.city ?? '', lat: props.ev.location?.lat ?? null, lng: props.ev.location?.lng ?? null })
const { data: templates } = await useAsyncData(`tpls-${props.ev.id}`, () => api<any[]>('/api/templates', { query: { orgId: props.ev.organizationId } }), { server: false })
const ask = (m: string) => window.confirm(m)
const busy = ref(false); const iso = (s: string) => (s ? new Date(s).toISOString() : null)
async function save() { busy.value = true; try { await api(`/api/manage/events/${props.ev.id}`, { method: 'PATCH', body: { title: f.title, description: f.description, category: f.category, visibility: f.visibility, startsAt: iso(f.startsAt), endsAt: iso(f.endsAt), salesOpenAt: iso(f.salesOpenAt), salesCloseAt: iso(f.salesCloseAt), capacity: f.capacity, maxPerOrder: f.maxPerOrder, themeId: f.themeId, accessTerms: f.accessTerms, templateId: f.templateId || null, offlineEnabled: f.offlineEnabled, transfersEnabled: f.transfersEnabled, refundPolicy: { allowed: f.refundAllowed, untilHoursBefore: f.refundHours }, ...(f.accessCode ? { accessCode: f.accessCode } : {}), venueName: f.venueName, address: f.address, city: f.city, lat: f.lat === null || f.lat === ('' as any) ? null : Number(f.lat), lng: f.lng === null || f.lng === ('' as any) ? null : Number(f.lng) } }); toast.ok('Événement enregistré'); emit('refresh') } catch (e) { toast.err(errMsg(e)) } finally { busy.value = false } }
async function status(action: string) { try { await api(`/api/manage/events/${props.ev.id}/status`, { method: 'POST', body: { action } }); toast.ok('Statut mis à jour'); emit('refresh') } catch (e) { toast.err(errMsg(e)) } }
async function dup() { try { const r = await api<{ id: string }>(`/api/manage/events/${props.ev.id}/duplicate`, { method: 'POST' }); await navigateTo(`/app/events/${r.id}`) } catch (e) { toast.err(errMsg(e)) } }
const poster = ref<HTMLInputElement>(); const posterUrl = ref('')
async function upPoster(e: Event) { const file = (e.target as HTMLInputElement).files?.[0]; if (!file) return; const fd = new FormData(); fd.append('orgId', props.ev.organizationId); fd.append('kind', 'poster'); fd.append('file', file); try { const r = await $fetch<any>('/api/uploads', { method: 'POST', body: fd }); await api(`/api/manage/events/${props.ev.id}`, { method: 'PATCH', body: { posterKey: r.key } }); posterUrl.value = r.url; toast.ok('Affiche enregistrée') } catch (er: any) { toast.err(er?.data?.statusMessage || 'Téléversement refusé') } }
const qr = ref(''); onMounted(async () => { qr.value = await qrFor(props.ev.shareUrl) })
const copy = async () => { await navigator.clipboard.writeText(props.ev.shareUrl); toast.ok('Lien copié') }
const camp = ref('instagram'); const campUrl = computed(() => `${props.ev.shareUrl}${props.ev.shareUrl.includes('?') ? '&' : '?'}ref=${encodeURIComponent(camp.value)}`)
void current
</script>
<template>
  <div class="grid gap-6 xl:grid-cols-[1fr_340px]">
    <form class="card space-y-5 p-5" @submit.prevent="save">
      <h2 class="text-lg font-bold">Informations</h2>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block sm:col-span-2"><span class="label">Titre</span><input v-model="f.title" required minlength="3" class="input"></label>
        <label class="block sm:col-span-2"><span class="label">Description</span><textarea v-model="f.description" rows="5" class="input !py-3" /></label>
        <label class="block"><span class="label">Catégorie</span><select v-model="f.category" class="input"><option v-for="c in ['soirée', 'concert', 'festival', 'conférence', 'anniversaire', 'privé']" :key="c">{{ c }}</option></select></label>
        <label class="block"><span class="label">Visibilité</span><select v-model="f.visibility" class="input"><option value="public">Public (listé)</option><option value="private">Privé (lien secret)</option><option value="invite">Sur invitation (code d’accès)</option></select></label>
        <label v-if="f.visibility !== 'public'" class="block sm:col-span-2"><span class="label">Code d’accès {{ ev.hasAccessCode ? '(défini : saisir pour le changer)' : '(facultatif pour un lien privé)' }}</span><input v-model="f.accessCode" minlength="4" class="input" autocomplete="off"></label>
        <label class="block"><span class="label">Début</span><input v-model="f.startsAt" type="datetime-local" required class="input"></label><label class="block"><span class="label">Fin</span><input v-model="f.endsAt" type="datetime-local" class="input"></label>
        <label class="block"><span class="label">Ouverture de la billetterie</span><input v-model="f.salesOpenAt" type="datetime-local" class="input"></label><label class="block"><span class="label">Fermeture de la billetterie</span><input v-model="f.salesCloseAt" type="datetime-local" class="input"></label>
        <label class="block"><span class="label">Capacité totale</span><input v-model.number="f.capacity" type="number" min="1" required class="input"></label><label class="block"><span class="label">Billets max. par commande</span><input v-model.number="f.maxPerOrder" type="number" min="1" max="50" class="input"></label></div>
      <h2 class="pt-2 text-lg font-bold">Lieu</h2>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block"><span class="label">Nom du lieu</span><input v-model="f.venueName" class="input"></label><label class="block"><span class="label">Ville</span><input v-model="f.city" class="input"></label><label class="block sm:col-span-2"><span class="label">Adresse</span><input v-model="f.address" class="input"></label><label class="block"><span class="label">Latitude</span><input v-model="f.lat" type="number" step="any" class="input"></label><label class="block"><span class="label">Longitude</span><input v-model="f.lng" type="number" step="any" class="input"></label></div>
      <h2 class="pt-2 text-lg font-bold">Billets et règles</h2>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block"><span class="label">Modèle de billet</span><select v-model="f.templateId" class="input"><option value="">Modèle par défaut</option><option v-for="t in templates" :key="t.id" :value="t.id">{{ t.name }}{{ t.published ? '' : ' (brouillon)' }}</option></select><NuxtLink to="/app/studio" class="hint underline">Ouvrir le Studio</NuxtLink></label>
        <label class="block"><span class="label">Conditions d’accès (imprimées sur le billet)</span><input v-model="f.accessTerms" maxlength="1000" class="input"></label>
        <label class="flex min-h-[44px] items-center gap-3"><input v-model="f.transfersEnabled" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]"> Billets transférables</label>
        <label class="flex min-h-[44px] items-center gap-3"><input v-model="f.offlineEnabled" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]"> Autoriser le mode scanner hors ligne</label>
        <label class="flex min-h-[44px] items-center gap-3"><input v-model="f.refundAllowed" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]"> Remboursements possibles</label><label v-if="f.refundAllowed" class="block"><span class="label">Jusqu’à (heures avant)</span><input v-model.number="f.refundHours" type="number" min="0" class="input"></label></div>
      <p v-if="f.offlineEnabled" class="rounded-xl border border-amber-400/40 bg-amber-400/10 p-3 text-sm text-amber-200">Hors ligne : plusieurs appareils déconnectés ne se voient pas entre eux. Un billet peut être accepté deux fois avant synchronisation ; les doublons sont signalés à la reconnexion.</p>
      <h2 class="pt-2 text-lg font-bold">Thème de la page de vente</h2><ThemeGallery v-model="f.themeId" scope="local" />
      <div class="flex justify-end"><button class="btn btn-primary" :disabled="busy">{{ busy ? 'Enregistrement…' : 'Enregistrer' }}</button></div>
    </form>
    <div class="space-y-5">
      <div class="card space-y-3 p-5"><h2 class="text-lg font-bold">Publication</h2><p class="text-sm"><span class="chip capitalize">{{ ev.status }}</span></p>
        <div class="grid gap-2"><button v-if="ev.status !== 'published'" class="btn btn-primary" @click="status('publish')">Publier / ouvrir les ventes</button><button v-if="ev.status === 'published'" class="btn btn-ghost" @click="status('suspend')">Suspendre les ventes</button><button v-if="ev.status === 'published'" class="btn btn-ghost" @click="status('close')">Clôturer les ventes</button><button class="btn btn-ghost" @click="dup">Dupliquer l’événement</button><button v-if="ev.status !== 'cancelled'" class="btn btn-danger" @click="ask('Annuler définitivement cet événement ?') && status('cancel')">Annuler l’événement</button></div></div>
      <div class="card space-y-3 p-5"><h2 class="text-lg font-bold">Affiche</h2><img v-if="posterUrl" :src="posterUrl" alt="Nouvelle affiche" class="w-full rounded-xl"><p v-else-if="ev.posterKey" class="text-sm text-muted">Affiche enregistrée.</p><button class="btn btn-ghost w-full" @click="poster?.click()">Téléverser (PNG/JPG, 6 Mo)</button><input ref="poster" type="file" accept="image/png,image/jpeg" class="hidden" @change="upPoster"></div>
      <div class="card space-y-3 p-5"><h2 class="text-lg font-bold">Partage et promotion</h2><div v-if="qr" class="mx-auto w-40 rounded-xl bg-white p-2"><img :src="qr" alt="QR code de la page publique" class="w-full"></div><input :value="ev.shareUrl" readonly class="input text-xs" aria-label="Lien de partage"><div class="flex gap-2"><button class="btn btn-ghost flex-1" @click="copy">Copier</button><a v-if="qr" :href="qr" download="qr-evenement.png" class="btn btn-ghost flex-1">QR (PNG)</a></div>
        <label class="block"><span class="label">Lien de campagne</span><select v-model="camp" class="input"><option>instagram</option><option>facebook</option><option>whatsapp</option><option>tiktok</option><option>affilie</option></select></label><input :value="campUrl" readonly class="input text-xs" aria-label="Lien de campagne"><p class="hint">Les ventes sont rattachées à la campagne et visibles dans l’onglet Commandes.</p></div>
    </div>
  </div>
</template>
